    /**
     * Tier Weight
     *
     * Weight of the tier in the confidence formula.
     */
    tier_weight: number;
    /**
     * Source Type
     *
     * Source kind, e.g. ClinVar, PubMed, HPO, fixture.
     */
    source_type: string;
    /**
     * Source Id
     *
     * Source identifier (PMID, NCT, VCV ...).
     */
    source_id?: string | null;
    /**
     * Url
     *
     * Link to the source.
     */
    url?: string | null;
    /**
     * Quote
     *
     * Exact supporting span from the source.
     */
    quote?: string | null;
    /**
     * Retrieved At
     *
     * When the source was retrieved.
     */
